/// d[key] = d.get(key, 0) + delta
pub fn addTo(d: *Dict, gpa: std.mem.Allocator, key: []const u8, delta: i64) !void {
    const gop = try d.getOrPut(gpa, key);
    if (!gop.found_existing) gop.value_ptr.* = 0;
    gop.value_ptr.* += delta;
}

/// d.get(key, default)
