test "put get contains" {
    const gpa = std.testing.allocator;
    var d: Dict = .empty;
    defer d.deinit(gpa);
    try d.put(gpa, "a", 1);
    try d.put(gpa, "b", 2);
    try d.put(gpa, "a", 10); // sobrescribe
    try std.testing.expectEqual(@as(?i64, 10), d.get("a"));
    try std.testing.expect(d.contains("b"));
    try std.testing.expect(!d.contains("zzz"));
