    var d: Dict = .empty;
    defer d.deinit(gpa);
    try addTo(&d, gpa, "hits", 1);
    try addTo(&d, gpa, "hits", 2);
    try addTo(&d, gpa, "miss", -4);
    try std.testing.expectEqual(@as(i64, 3), getOr(&d, "hits", 0));
    try std.testing.expectEqual(@as(i64, -4), getOr(&d, "miss", 0));
