    return a.age > b.age;
}

/// sorted(items, key=lambda p: p.age, reverse=reverse): copia nueva y orden ESTABLE.
pub fn sortedByAge(gpa: std.mem.Allocator, items: []const Person, reverse: bool) ![]Person {
