fn udpRoundTrip(io: std.Io, payload: []const u8, out: []u8) ![]const u8 {
    const any = net.IpAddress{ .ip4 = net.Ip4Address.loopback(0) };
    const rx = try any.bind(io, .{ .mode = .dgram });
    defer rx.close(io);
    const tx = try any.bind(io, .{ .mode = .dgram });
