test "// y % de Python con negativos" {
    try std.testing.expectEqual(@as(i32, -4), pyFloorDiv(-7, 2));
    try std.testing.expectEqual(@as(i32, 1), pyMod(-7, 2));
    try std.testing.expectEqual(@as(i32, -4), pyFloorDiv(7, -2));
    try std.testing.expectEqual(@as(i32, -1), pyMod(7, -2));
    try std.testing.expectEqual(@as(i32, 3), pyFloorDiv(7, 2));
    try std.testing.expectEqual(@as(i32, 1), pyMod(7, 2));
